// ---------- geometría ----------
const v2=p=>new THREE.Vector2(p[0],p[1]);
function shapeOf(P,holes){const s=new THREE.Shape(P.map(v2));(holes||[]).forEach(H=>s.holes.push(new THREE.Path(H.map(v2))));return s;}
