function boxFrom(P,z0,z1){const c=[(P[0][0]+P[2][0])/2,(P[0][1]+P[2][1])/2];const ex=[P[1][0]-P[0][0],P[1][1]-P[0][1]],ey=[P[2][0]-P[1][0],P[2][1]-P[1][1]];const g=new THREE.BoxGeometry(Math.hypot(...ex),z1-z0,Math.hypot(...ey));g.rotateY(Math.atan2(ex[1],ex[0]));g.translate(c[0],(z0+z1)/2,-c[1]);return g;}
